-- Realtime (postgres_changes respects the select policies above).
---------------------------------------------------------------------------
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table public.chat_messages, public.chat_participants;
  end if;
end $$;

insert into private.applied_migrations (version, name) values ('20261126001300', '20261126001300_chat.sql');

-- ===========================================================================
-- 20261126001400_chat_v2.sql
-- ===========================================================================
do $guard$ begin
  if exists (select 1 from private.applied_migrations where version = '20261126001400') then
    raise exception 'Migration 20261126001400 is already applied to this project. Use an update file instead.';
  end if;
end $guard$;

-- Chat v2 (plan items C2–C10). Additive: new columns with defaults, one new table, new
-- functions, one retention job. Existing chat rows stay as they are.
--
--   C2 attachments : files live in Storage under chat/<conversation_id>/…; a message keeps
--                    only a small list of {path, name, size, type}.
--   C3 presence    : private Realtime channels "pms-online" and "pms-typing:<conversation>".
--   C4 threads     : parent_id + reply counters kept by triggers.
--   C5 search      : generated tsvector + GIN index; RLS still decides what is found.
--   C6 reactions   : chat_reactions.
--   C7 retention   : nightly purge; periods in app_settings 'retention' (chat 6 months).
--   C8 keep-alive  : keep_alive() for the scheduled ping.
--   C10 usage      : admin_usage() and chat_files_to_purge() for Admin › Settings.

---------------------------------------------------------------------------
-- Messages: threads, attachments, search
---------------------------------------------------------------------------
alter table public.chat_messages
  add column parent_id uuid references public.chat_messages (id) on delete cascade,
  add column attachments jsonb not null default '[]',
  add column reply_count int not null default 0,
  add column last_reply_at timestamptz,
  add column search tsvector generated always as (to_tsvector('simple', body)) stored;

-- A message may be only attachments (empty text).
alter table public.chat_messages drop constraint chat_messages_body_check;
alter table public.chat_messages add constraint chat_messages_content check (
  length(body) <= 5000 and (length(trim(body)) > 0 or jsonb_array_length(attachments) > 0)
);
alter table public.chat_messages add constraint chat_messages_attachments_shape check (
  jsonb_typeof(attachments) = 'array' and jsonb_array_length(attachments) <= 10
);

create index chat_messages_parent_idx on public.chat_messages (parent_id, created_at) where parent_id is not null;
create index chat_messages_search_idx on public.chat_messages using gin (search);

-- Replies hang off a top-level message of the same conversation; attachments must sit in
-- this conversation's storage folder.
create function private.check_chat_message() returns trigger
language plpgsql set search_path = public as $$
declare
  a jsonb;
begin
  if new.parent_id is not null and not exists (
      select 1 from public.chat_messages p
      where p.id = new.parent_id and p.conversation_id = new.conversation_id and p.parent_id is null) then
    raise exception 'A reply must belong to a message in the same conversation';
  end if;
  for a in select value from jsonb_array_elements(new.attachments) loop
    if jsonb_typeof(a) <> 'object'
       or coalesce(a->>'name', '') = ''
       or coalesce(a->>'path', '') not like 'chat/' || new.conversation_id || '/%'
       or a->>'path' like '%..%' then
      raise exception 'Invalid attachment';
    end if;
  end loop;
  return new;
end $$;

create trigger chat_messages_check before insert on public.chat_messages
  for each row execute function private.check_chat_message();

-- Direct edits by people may change only the text. Triggers (reply counters) may update more.
create or replace function private.guard_chat_message_update() returns trigger
language plpgsql set search_path = public as $$
begin
  if current_user in ('authenticated', 'anon') then
    if (to_jsonb(new) - array['body', 'edited_at', 'search'])
       is distinct from (to_jsonb(old) - array['body', 'edited_at', 'search']) then
      raise exception 'Only the text of a message can be edited' using errcode = '42501';
    end if;
    new.edited_at := case when new.body is distinct from old.body then now() else old.edited_at end;
  end if;
  return new;
end $$;

create function private.chat_reply_counts() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' and new.parent_id is not null then
    update public.chat_messages
    set reply_count = reply_count + 1, last_reply_at = new.created_at
    where id = new.parent_id;
  elsif tg_op = 'DELETE' and old.parent_id is not null then
    update public.chat_messages
    set reply_count = greatest(reply_count - 1, 0)
    where id = old.parent_id;
  end if;
  return null;
end $$;

create trigger chat_messages_reply_counts after insert or delete on public.chat_messages
  for each row execute function private.chat_reply_counts();

revoke execute on function private.check_chat_message() from public;
revoke execute on function private.chat_reply_counts() from public;

---------------------------------------------------------------------------
-- Reactions
---------------------------------------------------------------------------
create table public.chat_reactions (
  message_id uuid not null references public.chat_messages (id) on delete cascade,
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  emoji text not null check (length(emoji) between 1 and 16),
  -- Copied from the message by a trigger, so reactions load per conversation.
  conversation_id uuid not null references public.chat_conversations (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (message_id, user_id, emoji)
);
create index chat_reactions_conversation_idx on public.chat_reactions (conversation_id);
create index chat_reactions_user_idx on public.chat_reactions (user_id);

create function private.set_reaction_conversation() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  select m.conversation_id into new.conversation_id from public.chat_messages m where m.id = new.message_id;
  if new.conversation_id is null then
    raise exception 'Message not found';
  end if;
  return new;
end $$;

create trigger chat_reactions_conversation before insert on public.chat_reactions
  for each row execute function private.set_reaction_conversation();
revoke execute on function private.set_reaction_conversation() from public;

alter table public.chat_reactions enable row level security;
create policy chat_reactions_select on public.chat_reactions for select to authenticated
  using (private.can_access_chat(conversation_id));
create policy chat_reactions_insert on public.chat_reactions for insert to authenticated
  with check (user_id = auth.uid() and private.can_access_chat(conversation_id));
create policy chat_reactions_delete on public.chat_reactions for delete to authenticated
  using (user_id = auth.uid());

revoke all on public.chat_reactions from anon, authenticated;
grant select, insert, delete on public.chat_reactions to authenticated;
grant all on public.chat_reactions to service_role;

---------------------------------------------------------------------------
-- Storage: chat/<conversation_id>/… follows chat access. Same function as before plus the
-- 'chat' branch.
---------------------------------------------------------------------------
create or replace function private.can_access_storage_path(p_path text) returns boolean
language plpgsql stable security definer set search_path = public as $$
declare
  v_kind text := split_part(p_path, '/', 1);
  v_id uuid;
begin
  begin
    v_id := split_part(p_path, '/', 2)::uuid;
  exception when others then
    return false;
  end;
  if v_kind = 'client' then
    return private.can_access_client(v_id);
  elsif v_kind = 'department' then
    return private.is_manager_or_admin() or v_id in (select private.my_department_ids());
  elsif v_kind = 'chat' then
    return private.can_access_chat(v_id);
  end if;
  return false;
end $$;

---------------------------------------------------------------------------
-- Presence and typing on private Realtime channels (nothing is stored).
---------------------------------------------------------------------------
create function private.can_use_realtime_topic(p_topic text) returns boolean
language plpgsql stable security definer set search_path = public as $$
begin
  if private.my_role() is null then
    return false;
  end if;
  if p_topic = 'pms-online' then
    return true;
  end if;
  if p_topic like 'pms-typing:%' then
    begin
      return private.can_access_chat(substr(p_topic, length('pms-typing:') + 1)::uuid);
    exception when others then
      return false;
    end;
  end if;
  return false;
end $$;
revoke execute on function private.can_use_realtime_topic(text) from public;
grant execute on function private.can_use_realtime_topic(text) to authenticated;

do $$
begin
  if to_regclass('realtime.messages') is null then
    raise notice 'realtime.messages not found; skipping presence policies';
    return;
  end if;
  execute $p$create policy "pms presence and typing receive" on realtime.messages
    for select to authenticated using (private.can_use_realtime_topic(realtime.topic()))$p$;
  execute $p$create policy "pms presence and typing send" on realtime.messages
    for insert to authenticated with check (private.can_use_realtime_topic(realtime.topic()))$p$;
end $$;

---------------------------------------------------------------------------
-- Retention (C7). Periods live in app_settings so an admin can change them.
---------------------------------------------------------------------------
insert into public.app_settings (key, value) values
  ('retention', '{"chat_months": 6, "notification_days": 90, "activity_months": 12}')
on conflict (key) do nothing;

create function private.purge_old_data() returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  r jsonb := coalesce((select value from public.app_settings where key = 'retention'), '{}');
  v_chat int;
  v_notes int;
  v_activity int;
  v_groups int;
begin
  -- A missing or zero period means "keep forever".
  delete from public.chat_messages
  where coalesce((r->>'chat_months')::int, 0) > 0
    and created_at < now() - make_interval(months => (r->>'chat_months')::int);
  get diagnostics v_chat = row_count;

  delete from public.notifications
  where read_at is not null
    and coalesce((r->>'notification_days')::int, 0) > 0
    and created_at < now() - make_interval(days => (r->>'notification_days')::int);
  get diagnostics v_notes = row_count;

  delete from public.activity_log
  where coalesce((r->>'activity_months')::int, 0) > 0
    and created_at < now() - make_interval(months => (r->>'activity_months')::int);
  get diagnostics v_activity = row_count;

  -- Groups everyone has left.
  delete from public.chat_conversations c
  where c.kind = 'group'
    and not exists (select 1 from public.chat_participants p where p.conversation_id = c.id);
  get diagnostics v_groups = row_count;

  return jsonb_build_object('chat_messages', v_chat, 'notifications', v_notes,
                            'activity_log', v_activity, 'empty_groups', v_groups);
end $$;
revoke execute on function private.purge_old_data() from public;

do $$
begin
  if not exists (select 1 from pg_namespace where nspname = 'cron') then
    raise notice 'pg_cron not available; skipping schedule';
    return;
  end if;
  -- 03:00 IST.
  perform cron.schedule('pms-retention', '30 21 * * *', $job$select private.purge_old_data()$job$);
end $$;

---------------------------------------------------------------------------
-- Usage (C10) and chat file clean-up. Storage files can only be deleted through the Storage
-- API, so the database lists them and the admin's browser removes them.
---------------------------------------------------------------------------
-- Chat files no message points to any more (message deleted or expired), older than a day
-- so uploads in progress are never listed.
create function private.chat_orphan_files() returns table (name text, bytes bigint)
language sql stable security definer set search_path = public as $$
  select o.name, coalesce((o.metadata->>'size')::bigint, 0)
  from storage.objects o
  where o.bucket_id = 'files'
    and o.name like 'chat/%'
    and o.created_at < now() - interval '1 day'
    and not exists (
      select 1 from public.chat_messages m
      where m.attachments @> jsonb_build_array(jsonb_build_object('path', o.name)))
$$;
revoke execute on function private.chat_orphan_files() from public;

create function public.chat_files_to_purge() returns table (name text, bytes bigint)
language plpgsql stable security definer set search_path = public as $$
begin
  if not private.is_admin() then
    raise exception 'Only admins can clean up files' using errcode = '42501';
  end if;
  return query select f.name, f.bytes from private.chat_orphan_files() f limit 1000;
end $$;

create function public.admin_usage() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not private.is_admin() then
    raise exception 'Only admins can see usage' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'db_bytes', pg_database_size(current_database()),
    'tables', (
      select coalesce(jsonb_agg(jsonb_build_object('name', t.relname, 'bytes', t.bytes) order by t.bytes desc), '[]')
      from (
        select c.relname, pg_total_relation_size(c.oid) as bytes
        from pg_class c join pg_namespace n on n.oid = c.relnamespace
        where n.nspname = 'public' and c.relkind = 'r'
        order by 2 desc limit 8
      ) t),
    'storage_bytes', (select coalesce(sum((o.metadata->>'size')::bigint), 0) from storage.objects o where o.bucket_id = 'files'),
    'storage_files', (select count(*) from storage.objects o where o.bucket_id = 'files'),
    'storage_by_area', (
      select coalesce(jsonb_object_agg(x.area, x.bytes), '{}')
      from (
        select split_part(o.name, '/', 1) as area, coalesce(sum((o.metadata->>'size')::bigint), 0) as bytes
        from storage.objects o where o.bucket_id = 'files' group by 1
      ) x),
    'chat_messages', (select count(*) from public.chat_messages),
    'oldest_chat_message', (select min(created_at) from public.chat_messages),
    'purgeable_files', (select count(*) from private.chat_orphan_files()),
    'purgeable_bytes', (select coalesce(sum(f.bytes), 0) from private.chat_orphan_files() f),
    'retention', (select value from public.app_settings where key = 'retention')
  );
end $$;

---------------------------------------------------------------------------
-- Keep-alive (C8): the scheduled GitHub Action calls this with the public key so a quiet
-- week never pauses the free project. Returns nothing sensitive.
---------------------------------------------------------------------------
create function public.keep_alive() returns text
language sql stable security definer set search_path = public as $$
  select 'ok:' || (select count(*) from public.app_settings)::text
$$;

revoke execute on function public.chat_files_to_purge() from public, anon;
revoke execute on function public.admin_usage() from public, anon;
revoke execute on function public.keep_alive() from public;
grant execute on function public.chat_files_to_purge() to authenticated;
grant execute on function public.admin_usage() to authenticated;
grant execute on function public.keep_alive() to anon, authenticated;

